40	/// Minimum number of fence characters required per CommonMark §4.5.
41	const MIN_FENCE_LENGTH: usize = 3;
42	
43	/// Consume indent whitespace (spaces/tabs) from source bytes.
44	///
45	/// Tracks column width where tabs expand to next multiple of 4.
46	/// Returns `Some(new_idx)` on success, or `None` if required indent wasn't met.
47	fn consume_indent(source: &[u8], mut idx: usize, limit: usize, required: bool) -> Option<usize> {
48	    let mut column = 0usize;
49	    while column < limit {
50	        match source.get(idx).copied() {
51	            Some(b' ') => {
52	                column += 1;
53	                idx += 1;
54	            }
55	            Some(b'\t') => {
56	                let tab_width = TAB_STOP_SPACES - (column % TAB_STOP_SPACES);
57	                // For optional indent, don't exceed limit with tab
58	                if !required && column + tab_width > limit {
59	                    break;
60	                }
61	                column += tab_width;
62	                idx += 1;
63	            }
64	            _ => {
65	                if required {
66	                    return None;
67	                }
68	                break;
69	            }
70	        }
71	    }
72	    Some(idx)
73	}
