638	pub(crate) fn parse_paragraph(p: &mut MarkdownParser) -> ParsedSyntax {
639	    let m = p.start();
640	
641	    let inline_start: usize = p.cur_range().start().into();
642	    parse_inline_item_list(p);
643	    let inline_end: usize = p.cur_range().start().into();
644	
645	    let has_inline_content = inline_has_non_whitespace(p, inline_start, inline_end);
646	    let allow_setext = has_inline_content && allow_setext_heading(p);
647	
648	    // Check if this paragraph is followed by a setext heading underline
649	    // MD_SETEXT_UNDERLINE_LITERAL is for `=` underlines
650	    // MD_THEMATIC_BREAK_LITERAL with only `-` is also a setext underline (H2)
651	    let completed = if allow_setext && p.at(MD_SETEXT_UNDERLINE_LITERAL) {
652	        let indent = real_line_indent_from_source(p);
653	        if indent < INDENT_CODE_BLOCK_SPACES {
654	            // This is a setext heading (H1 with `=`) - consume the underline
655	            p.bump(MD_SETEXT_UNDERLINE_LITERAL);
656	            m.complete(p, MD_SETEXT_HEADER)
657	        } else {
658	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
659	            m.complete(p, MD_PARAGRAPH)
660	        }
661	    } else if allow_setext && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
662	        let indent = real_line_indent_from_source(p);
663	        if indent < INDENT_CODE_BLOCK_SPACES {
664	            // This is a setext heading (H2 with `-`) - remap token and consume
665	            p.bump_remap(MD_SETEXT_UNDERLINE_LITERAL);
666	            m.complete(p, MD_SETEXT_HEADER)
667	        } else {
668	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
669	            m.complete(p, MD_PARAGRAPH)
670	        }
671	    } else {
672	        m.complete(p, MD_PARAGRAPH)
673	    };
674	    Present(completed)
675	}
