/// Return the range of the first stray backtick in a backtick fence's info string.
///
/// Assumes the parser is positioned at the opening fence. Returns `Some(range)`
/// pointing at the first backtick character that appears after the opening
/// backtick fence run on the same line (a §4.5 violation), or `None` when the
/// fence is a tilde fence or the info string contains no backtick.
pub(crate) fn info_string_stray_backtick(p: &mut MarkdownParser) -> Option<TextRange> {
    p.lookahead(|p| {
        if p.at(TRIPLE_TILDE) {
            return None;
        }

        if p.at(T!["```"]) {
            p.bump(T!["```"]);
        } else if p.at(BACKTICK) {
            p.bump(BACKTICK);
        } else {
            return None;
        }

        while !p.at_inline_end() {
            if p.at(BACKTICK) || p.at(T!["```"]) {
                // Point precisely at the first stray backtick character.
                let start = p.cur_range().start();
                return Some(TextRange::new(start, start + TextSize::from(1)));
            }
            p.bump(p.cur());
        }

        None
    })
}

/// If the current line opens a backtick code fence whose info string contains a
/// backtick, return the range of the first stray backtick.
///
/// Mirrors [`at_fenced_code_block`]'s line-start and indentation checks, but
/// instead of rejecting the fence it reports the offending backtick so the
/// caller can emit a diagnostic (CommonMark §4.5). Returns `None` for tilde
/// fences and for backtick fences with a valid info string.
pub(crate) fn backtick_fence_info_stray_backtick(p: &mut MarkdownParser) -> Option<TextRange> {
    p.lookahead(|p| {
        if !p.at_start_of_input() && !is_line_start_within_indent(p, MAX_BLOCK_PREFIX_INDENT) {
            return None;
        }
        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);

        let rest = p.source_after_current();
        let (fence_char, _) = detect_fence(rest)?;
        if fence_char != '`' {
            return None;
        }
        info_string_stray_backtick(p)
    })
